import { readFileSync, writeFileSync } from 'fs';
import { checkpoint } from '@tigrisdata/agent-kit';
import { join } from 'path';

async function main() {
  const dir = '/home/user/ckpt-tag';

  // 1. Read the build id
  const buildIdPath = join(dir, 'build_id.txt');
  const buildId = readFileSync(buildIdPath, 'utf-8').trim();

  // 2. Compute a unix timestamp
  const unixTimestamp = Math.floor(Date.now() / 1000);

  // 3. Take a named checkpoint
  const name = `release-${buildId}-${unixTimestamp}`;
  const { data: ckpt, error } = await checkpoint("agent-pipeline-data", { name });

  if (error) {
    console.error("Error creating checkpoint:", error);
    process.exit(1);
  }

  // 4. Persist the result
  const snapshotJsonPath = join(dir, 'snapshot.json');
  const result = {
    snapshotId: ckpt.snapshotId,
    name: name
  };

  writeFileSync(snapshotJsonPath, JSON.stringify(result, null, 2));
  console.log("Checkpoint created successfully:", result);
}

main().catch(err => {
  console.error("Unhandled error:", err);
  process.exit(1);
});

